local p=fu:GetResolve():GetProjectManager():GetCurrentProject();print('V26_STATUS',p:GetName(),p:IsRenderingInProgress());for i=1,p:GetTimelineCount() do local t=p:GetTimelineByIndex(i);if string.find(t:GetName(),'v26') then print(t:GetName(),t:GetEndFrame());if string.find(t:GetName(),'FINAL') then dump(t:GetItemListInTrack('audio',1)[1]:GetSpeed()) end end end;for _,j in ipairs(p:GetRenderJobList()) do if string.find(j.OutputFilename or '', 'final120') or string.find(j.OutputFilename or '', 'clean100') then print(j.JobId,j.OutputFilename);dump(p:GetRenderJobStatus(j.JobId)) end end